// Resolve install order for packages with dependencies (topological)
const pkgs={"app": ["lib", "util"], "lib": ["base"], "util": [], "base": []};
const order=[],done={};
const build=p=>{if(done[p])return;done[p]=1;(pkgs[p]||[]).forEach(build);order.push(p);};
Object.keys(pkgs).forEach(build);
console.log('install order:',order.join(' -> '));

